diff --git a/src/dsql/DdlNodes.epp b/src/dsql/DdlNodes.epp
index 4e8c5c9f4cf..9097c30658e 100644
--- a/src/dsql/DdlNodes.epp
+++ b/src/dsql/DdlNodes.epp
@@ -1446,10 +1446,6 @@ void CommentOnNode::checkPermission(thread_db* tdbb, jrd_tra* transaction)
 			SCL_check_view(tdbb, name, SCL_alter);
 			break;

-		case obj_procedure:
-			SCL_check_procedure(tdbb, name, SCL_alter);
-			break;
-
 		case obj_trigger:
 		{
 			const auto relationName = getTriggerRelationName(tdbb, transaction, name);
@@ -1461,7 +1457,19 @@ void CommentOnNode::checkPermission(thread_db* tdbb, jrd_tra* transaction)
 		}

 		case obj_udf:
-			SCL_check_function(tdbb, name, SCL_alter);
+		case obj_procedure:
+			if (name.package.hasData())
+			{
+				const auto package = name.getSchemaAndPackage();
+				SCL_check_package(tdbb, package, SCL_alter);
+			}
+			else
+			{
+				if (objType == obj_udf)
+					SCL_check_function(tdbb, name, SCL_alter);
+				else
+					SCL_check_procedure(tdbb, name, SCL_alter);
+			}
 			break;

 		case obj_blob_filter:
